FUNCTION_BLOCK FB_Aerospace_AutoclaveThermalPressure
(* ========================================================================================= *)
(* LUMINA CYBER-PHYSICAL AUTOMATION ARCHITECTURE - MISSION-CRITICAL AEROSPACE CLASS A       *)
(* ----------------------------------------------------------------------------------------- *)
(* DOMAIN: AEROSPACE AUTOCLAVE COMPOSITE CURING                                              *)
(* SUBSYSTEM: Multi-Point Thermocouple Gradient Heat Transfer & Resin Viscosity Pressure    *)
(* TARGET SPECIFICATION: Boeing BMS 8-276 / AMS 2750G / MIL-HDBK-17 Class 1 Primary Structure*)
(* ARCHITECT: 75+ Yr Automation Fellow & Cyber-Physical Systems Chair                        *)
(*                                                                                           *)
(* MATHEMATICAL FORMULATION & ALGORITHMIC TAXONOMY:                                          *)
(* 1. TRIPLE MODULAR REDUNDANCY (2oo3) VOTING:                                              *)
(*    Discrete majority median selection across Channel A, B, C thermocouple sets with        *)
(*    stochastic outlier identification and sensor degradation bitmask latching.             *)
(*                                                                                           *)
(* 2. FINITE-DIFFERENCE THERMAL GRADIENT OBSERVER & DISTRIBUTED STATE-SPACE:                *)
(*    dT/dt rate filtering using recursive exponential smoothing filter (alpha = 0.12):     *)
(*    dT_filt[k] = alpha * ((T[k] - T[k-1])/dt) + (1 - alpha) * dT_filt[k-1]                *)
(*    Inter-laminate delta: Delta_T_gradient = Max(T_surf, T_core, T_tool) - Min(...)        *)
(*                                                                                           *)
(* 3. RESIN RHEOLOGY & CURE KINETICS (KAMAL-SOUROUR AUTOCATALYTIC FORMULATION):              *)
(*    dAlpha/dt = (k1*exp(-E1/RT) + k2*exp(-E2/RT) * Alpha^m) * (1 - Alpha)^n               *)
(*    Viscosity Profile: eta(T, Alpha) = eta_0 * exp(E_eta / RT) * (Alpha_gel/(Alpha_gel-Alpha))^(A + B*Alpha) *)
(*    Dynamic Pressure Trigger window: eta <= eta_min_threshold AND Alpha < Alpha_gel        *)
(*                                                                                           *)
(* 4. 2-INPUT / 2-OUTPUT DECOUPLED THERMAL-PNEUMATIC PREDICTIVE CONSTRAINED CONTROLLER:      *)
(*    Graceful degradation upon sensor failover, vacuum breach, or runaway exotherm.         *)
(* ========================================================================================= *)

VAR_INPUT
    bEnable                     : BOOL;     (* System master cure cycle enable command *)
    bSafetyInterlockOK          : BOOL;     (* Autoclave hydraulic door lock ring & vessel seal safety permit *)
    bEmergencyAbortCmd          : BOOL;     (* External hard-wired manual abort & rapid depressurize request *)

    (* --- Redundant Temperature Sensor Inputs [deg C] --- *)
    rTC_Zone1_LeadingEdge_A     : REAL;     (* Part Leading Edge Thermocouple - Ch A [deg C] *)
    rTC_Zone1_LeadingEdge_B     : REAL;     (* Part Leading Edge Thermocouple - Ch B [deg C] *)
    rTC_Zone1_LeadingEdge_C     : REAL;     (* Part Leading Edge Thermocouple - Ch C [deg C] *)
    rTC_Zone2_LaminateCore      : REAL;     (* Mid-plane thick section embedded core TC [deg C] *)
    rTC_Zone3_InvarToolBase     : REAL;     (* Invar master mold structural base plate TC [deg C] *)
    rTC_Zone4_ChamberAir        : REAL;     (* Forced convection internal air stream TC [deg C] *)

    (* --- Pressure and Vacuum Instrumentation [bar], [mbar] --- *)
    rAutoclaveVesselPressure_Bar: REAL;     (* Internal chamber hydrostatic pressure transducer [bar] *)
    rVacuumBagPressure_mbar     : REAL;     (* Vacuum bag hermetic core absolute pressure sensor [mbar] *)

    (* --- Thermal Profile Setpoints & Limits [deg C], [deg C/min], [%] --- *)
    rSetpointCureTemp           : REAL;     (* Final isothermal soak setpoint [deg C] (e.g. 177.0 C) *)
    rRampRateSetpoint           : REAL;     (* Programmed heating rate limit [deg C/min] (e.g. 1.8 C/min) *)
    rMaxAllowableGradient       : REAL;     (* Max allowable spatial gradient limit [deg C] (e.g. 12.0 C) *)
    rTargetAutoclavePressure_Bar: REAL;     (* High-pressure consolidation setpoint [bar] (e.g. 6.89 bar) *)
    rMinViscosityPressureWindow : REAL;     (* Target threshold viscosity to trigger pressure [Pa*s] *)

    (* --- Execution Cycle Parameters --- *)
    tScanCycleTime              : TIME;     (* Deterministic cycle scan delta time basis (e.g. T#100MS) *)
END_VAR

VAR_OUTPUT
    bSystemReady                : BOOL;     (* System ready and all safety interlocks satisfied *)
    bCycleCompleted             : BOOL;     (* Cure cycle finished, cooled down, and certified completed *)
    bGracefulDegradationActive  : BOOL;     (* Redundancy lost / operating under degraded fallback control *)

    (* --- Continuous Process Manipulated Actuators [%] --- *)
    rHeaterThyristorPowerPct    : REAL;     (* Modulated 3-phase electric circulation heater SCR power [%] *)
    rExchangerCoolingDamperPct  : REAL;     (* Modulated liquid-nitrogen / chilled water exchanger damper [%] *)
    rPressurizationValvePct     : REAL;     (* Nitrogen supply proportional pressurization valve [%] *)
    rExhaustBleedValvePct       : REAL;     (* Vessel atmosphere proportional depressurization valve [%] *)
    rVacuumBagVentValvePct      : REAL;     (* Vacuum bag atmospheric venting / positive debulking valve [%] *)

    (* --- Advanced Process State Observations & Kinetic Models --- *)
    rVotedLeadingEdgeTemp       : REAL;     (* 2oo3 TMR resolved leading edge temperature [deg C] *)
    rObservedMaxGradient_degC   : REAL;     (* Instantaneous worst-case thermal gradient Delta-T [deg C] *)
    rFilteredHeatingRate_C_min  : REAL;     (* Filtered thermal ramp derivative dT/dt [deg C/min] *)
    rEstimatedDegreeOfCure      : REAL;     (* Integrated Kamal-Sourour degree of cure Alpha [0.000 to 1.000] *)
    rEstimatedViscosity_Pa_s    : REAL;     (* Estimated dynamic resin rheology viscosity [Pa*s] *)

    (* --- Industrial Diagnostic and Status Registers --- *)
    wAlarmWord                  : WORD;     (* Bit-encoded safety-critical trip alarm register *)
    wWarningWord                : WORD;     (* Bit-encoded non-critical warning and sensor drift register *)
    iCurrentCurePhase           : INT;      (* Active cure profile execution phase index [0..999] *)
    sCurrentPhaseDescription    : STRING[32];(* Human-readable HMI cure phase status string *)
END_VAR

VAR
    (* --- Internal State Machine Variables --- *)
    iSubState                   : INT := 0;
    tStateTimer                 : TON;
    tVacuumHoldTimer            : TON;
    tCureDwellTimer             : TON;
    tExothermGraceTimer         : TON;

    (* --- 2oo3 Triple Modular Redundancy (TMR) Data Structures --- *)
    bSensorFail_Zone1_A         : BOOL := FALSE;
    bSensorFail_Zone1_B         : BOOL := FALSE;
    bSensorFail_Zone1_C         : BOOL := FALSE;
    iHealthySensorCount         : INT := 3;
    rSensorDeviationLimit       : REAL := 5.0; (* Maximum allowed inter-sensor discrepancy in deg C *)
    rTMR_MedianVal              : REAL := 20.0;

    (* --- Finite-Difference Derivative & Filter Variables --- *)
    rPreviousVotedTemp          : REAL := 20.0;
    rRawDeltaTemp               : REAL := 0.0;
    rDeltaSeconds               : REAL := 0.1;
    rAlphaRampFilter            : REAL := 0.12; (* Recursive digital low-pass coefficient *)

    (* --- Kinetic Cure and Viscosity Internal Parameters (CYCOM 977-2 / Epoxy Equivalent) --- *)
    rR_GasConstant              : REAL := 8.31446;  (* Universal gas constant J/(mol*K) *)
    rE1_ActivationEnergy        : REAL := 65000.0;  (* Arrhenius primary activation energy J/mol *)
    rE2_ActivationEnergy        : REAL := 58000.0;  (* Arrhenius secondary catalytic energy J/mol *)
    rA1_PreExponential          : REAL := 12500.0;  (* Pre-exponential rate factor 1 [1/s] *)
    rA2_PreExponential          : REAL := 85000.0;  (* Pre-exponential rate factor 2 [1/s] *)
    rPowerM                     : REAL := 0.75;     (* Autocatalytic reaction order m *)
    rPowerN                     : REAL := 1.45;     (* Autocatalytic reaction order n *)
    rGelationAlpha              : REAL := 0.42;     (* Gelation point degree of cure *)
    rBaseViscosity              : REAL := 0.085;    (* Monomer base viscosity pre-factor [Pa*s] *)
    rViscosityActEnergy         : REAL := 38000.0;  (* Flow activation energy J/mol *)
    rAbsoluteTempKelvin         : REAL := 293.15;
    rRateConstantK1             : REAL := 0.0;
    rRateConstantK2             : REAL := 0.0;
    rInstantaneousRate          : REAL := 0.0;
    bResinMinimumViscosityMet   : BOOL := FALSE;
    bGelationReached            : BOOL := FALSE;

    (* --- Constrained Model Predictive / Decoupled Thermal-Pressure PID States --- *)
    rThermalError               : REAL := 0.0;
    rThermalIntegral            : REAL := 0.0;
    rThermalDerivative          : REAL := 0.0;
    rPrevThermalError           : REAL := 0.0;
    rThermalIntegralMax         : REAL := 80.0;
    rThermalIntegralMin         : REAL := -40.0;
    rHeatOutputEffort           : REAL := 0.0;

    rPressureError              : REAL := 0.0;
    rPressureIntegral           : REAL := 0.0;
    rPressureEffort             : REAL := 0.0;

    (* --- Thermal Gradient Surveillance Memory --- *)
    rMinPartTemp                : REAL := 20.0;
    rMaxPartTemp                : REAL := 20.0;
    rVacuumIntegrityStart_mbar  : REAL := 0.0;
    rVacuumLeakRate_mbar_per_min: REAL := 0.0;

    (* --- Diagnostic Alarm Constants --- *)
    C_ALARM_INTERLOCK_BREACH    : WORD := 16#0001; (* Bit 0: Autoclave pressure lock lost *)
    C_ALARM_EXOTHERM_RUNAWAY    : WORD := 16#0002; (* Bit 1: Uncontrolled part core exotherm *)
    C_ALARM_GRADIENT_EXCEEDED   : WORD := 16#0004; (* Bit 2: Delta-T thermal stress exceeded *)
    C_ALARM_VACUUM_BAG_BREACH   : WORD := 16#0008; (* Bit 3: Bag puncture / vacuum decay *)
    C_ALARM_PRESSURE_HYDRAULIC  : WORD := 16#0010; (* Bit 4: Vessel overpressure limit *)
    C_ALARM_SENSOR_TMR_FAIL     : WORD := 16#0020; (* Bit 5: 2oo3 majority sensor loss *)
    C_ALARM_MANUAL_EMERGENCY    : WORD := 16#0040; (* Bit 6: Operator or E-Stop initiated *)

    C_WARN_TC_CHANNEL_A_DRIFT   : WORD := 16#0001; (* Bit 0: Zone 1 Channel A deviated *)
    C_WARN_TC_CHANNEL_B_DRIFT   : WORD := 16#0002; (* Bit 1: Zone 1 Channel B deviated *)
    C_WARN_TC_CHANNEL_C_DRIFT   : WORD := 16#0004; (* Bit 2: Zone 1 Channel C deviated *)
    C_WARN_RAMP_LAG             : WORD := 16#0008; (* Bit 3: Thermal response lagging profile *)
    C_WARN_COOLING_INSUFFICIENT : WORD := 16#0010; (* Bit 4: Exchanger capacity limit near saturation *)
END_VAR

(* ========================================================================================= *)
(* CRITICAL HARDWARE INTERLOCK & SAFETY SUPERVISORY LAYER                                   *)
(* ========================================================================================= *)
wAlarmWord := 16#0000;
wWarningWord := 16#0000;

IF NOT bSafetyInterlockOK THEN
    wAlarmWord := wAlarmWord OR C_ALARM_INTERLOCK_BREACH;
    iCurrentCurePhase := 999; (* Transition directly to emergency shutdown *)
END_IF;

IF bEmergencyAbortCmd THEN
    wAlarmWord := wAlarmWord OR C_ALARM_MANUAL_EMERGENCY;
    iCurrentCurePhase := 999;
END_IF;

(* Delta time calculation in floating-point seconds *)
IF TIME_TO_REAL(tScanCycleTime) > 0.001 THEN
    rDeltaSeconds := TIME_TO_REAL(tScanCycleTime) / 1000.0;
ELSE
    rDeltaSeconds := 0.1; (* Default nominal 100 ms *)
END_IF;

(* ========================================================================================= *)
(* ALGORITHM BLOCK 1: TRIPLE MODULAR REDUNDANCY (2oo3) TMR SENSOR VOTING                     *)
(* ========================================================================================= *)
(* Check mutual discrepancies between Channel A, B, and C *)
bSensorFail_Zone1_A := (ABS(rTC_Zone1_LeadingEdge_A - rTC_Zone1_LeadingEdge_B) > rSensorDeviationLimit) AND 
                       (ABS(rTC_Zone1_LeadingEdge_A - rTC_Zone1_LeadingEdge_C) > rSensorDeviationLimit);

bSensorFail_Zone1_B := (ABS(rTC_Zone1_LeadingEdge_B - rTC_Zone1_LeadingEdge_A) > rSensorDeviationLimit) AND 
                       (ABS(rTC_Zone1_LeadingEdge_B - rTC_Zone1_LeadingEdge_C) > rSensorDeviationLimit);

bSensorFail_Zone1_C := (ABS(rTC_Zone1_LeadingEdge_C - rTC_Zone1_LeadingEdge_A) > rSensorDeviationLimit) AND 
                       (ABS(rTC_Zone1_LeadingEdge_C - rTC_Zone1_LeadingEdge_B) > rSensorDeviationLimit);

iHealthySensorCount := 3;
IF bSensorFail_Zone1_A THEN
    wWarningWord := wWarningWord OR C_WARN_TC_CHANNEL_A_DRIFT;
    iHealthySensorCount := iHealthySensorCount - 1;
END_IF;
IF bSensorFail_Zone1_B THEN
    wWarningWord := wWarningWord OR C_WARN_TC_CHANNEL_B_DRIFT;
    iHealthySensorCount := iHealthySensorCount - 1;
END_IF;
IF bSensorFail_Zone1_C THEN
    wWarningWord := wWarningWord OR C_WARN_TC_CHANNEL_C_DRIFT;
    iHealthySensorCount := iHealthySensorCount - 1;
END_IF;

(* Graceful Degradation & Majority Median Vote Selection *)
IF iHealthySensorCount >= 2 THEN
    IF NOT bSensorFail_Zone1_A AND NOT bSensorFail_Zone1_B AND NOT bSensorFail_Zone1_C THEN
        (* All three healthy: Standard Median Selection *)
        IF (rTC_Zone1_LeadingEdge_A >= rTC_Zone1_LeadingEdge_B AND rTC_Zone1_LeadingEdge_A <= rTC_Zone1_LeadingEdge_C) OR 
           (rTC_Zone1_LeadingEdge_A <= rTC_Zone1_LeadingEdge_B AND rTC_Zone1_LeadingEdge_A >= rTC_Zone1_LeadingEdge_C) THEN
            rTMR_MedianVal := rTC_Zone1_LeadingEdge_A;
        ELSIF (rTC_Zone1_LeadingEdge_B >= rTC_Zone1_LeadingEdge_A AND rTC_Zone1_LeadingEdge_B <= rTC_Zone1_LeadingEdge_C) OR 
              (rTC_Zone1_LeadingEdge_B <= rTC_Zone1_LeadingEdge_A AND rTC_Zone1_LeadingEdge_B >= rTC_Zone1_LeadingEdge_C) THEN
            rTMR_MedianVal := rTC_Zone1_LeadingEdge_B;
        ELSE
            rTMR_MedianVal := rTC_Zone1_LeadingEdge_C;
        END_IF;
        bGracefulDegradationActive := FALSE;
    ELSE
        (* Dual-channel redundancy: Average remaining valid channels *)
        bGracefulDegradationActive := TRUE;
        IF bSensorFail_Zone1_A THEN
            rTMR_MedianVal := (rTC_Zone1_LeadingEdge_B + rTC_Zone1_LeadingEdge_C) / 2.0;
        ELSIF bSensorFail_Zone1_B THEN
            rTMR_MedianVal := (rTC_Zone1_LeadingEdge_A + rTC_Zone1_LeadingEdge_C) / 2.0;
        ELSE
            rTMR_MedianVal := (rTC_Zone1_LeadingEdge_A + rTC_Zone1_LeadingEdge_B) / 2.0;
        END_IF;
    END_IF;
ELSE
    (* Majority voting collapse - Multiple sensor failures *)
    wAlarmWord := wAlarmWord OR C_ALARM_SENSOR_TMR_FAIL;
    bGracefulDegradationActive := TRUE;
    rTMR_MedianVal := rTC_Zone4_ChamberAir; (* Ultimate fallback to convective air temperature *)
END_IF;

rVotedLeadingEdgeTemp := rTMR_MedianVal;

(* ========================================================================================= *)
(* ALGORITHM BLOCK 2: FINITE-DIFFERENCE THERMAL GRADIENT & RATE DERIVATIVE OBSERVER          *)
(* ========================================================================================= *)
(* Calculate discrete heating rate: dT/dt [deg C/min] *)
IF rDeltaSeconds > 0.0 THEN
    rRawDeltaTemp := ((rVotedLeadingEdgeTemp - rPreviousVotedTemp) / rDeltaSeconds) * 60.0;
    rFilteredHeatingRate_C_min := (rAlphaRampFilter * rRawDeltaTemp) + ((1.0 - rAlphaRampFilter) * rFilteredHeatingRate_C_min);
    rPreviousVotedTemp := rVotedLeadingEdgeTemp;
END_IF;

(* Multi-point spatial gradient identification *)
rMaxPartTemp := rVotedLeadingEdgeTemp;
IF rTC_Zone2_LaminateCore > rMaxPartTemp THEN rMaxPartTemp := rTC_Zone2_LaminateCore; END_IF;
IF rTC_Zone3_InvarToolBase > rMaxPartTemp THEN rMaxPartTemp := rTC_Zone3_InvarToolBase; END_IF;

rMinPartTemp := rVotedLeadingEdgeTemp;
IF rTC_Zone2_LaminateCore < rMinPartTemp THEN rMinPartTemp := rTC_Zone2_LaminateCore; END_IF;
IF rTC_Zone3_InvarToolBase < rMinPartTemp THEN rMinPartTemp := rTC_Zone3_InvarToolBase; END_IF;

rObservedMaxGradient_degC := rMaxPartTemp - rMinPartTemp;

(* Spatial gradient limit check *)
IF rObservedMaxGradient_degC > rMaxAllowableGradient THEN
    wAlarmWord := wAlarmWord OR C_ALARM_GRADIENT_EXCEEDED;
END_IF;

(* Core exotherm runaway identification: Core temperature significantly hotter than ambient and leading edge *)
IF (rTC_Zone2_LaminateCore > (rTC_Zone4_ChamberAir + 8.0)) AND (rFilteredHeatingRate_C_min > 3.0) THEN
    wAlarmWord := wAlarmWord OR C_ALARM_EXOTHERM_RUNAWAY;
END_IF;

(* ========================================================================================= *)
(* ALGORITHM BLOCK 3: KAMAL-SOUROUR CURE KINETICS & RESIN VISCOSITY PREDICTOR               *)
(* ========================================================================================= *)
rAbsoluteTempKelvin := rVotedLeadingEdgeTemp + 273.15;
IF rAbsoluteTempKelvin < 273.15 THEN rAbsoluteTempKelvin := 273.15; END_IF;

(* Arrhenius Reaction Constants *)
rRateConstantK1 := rA1_PreExponential * EXP(-1.0 * (rE1_ActivationEnergy / (rR_GasConstant * rAbsoluteTempKelvin)));
rRateConstantK2 := rA2_PreExponential * EXP(-1.0 * (rE2_ActivationEnergy / (rR_GasConstant * rAbsoluteTempKelvin)));

(* Autocatalytic Reaction Differential: dAlpha/dt *)
IF rEstimatedDegreeOfCure < 0.999 AND rEstimatedDegreeOfCure >= 0.000 THEN
    rInstantaneousRate := (rRateConstantK1 + rRateConstantK2 * EXPT(rEstimatedDegreeOfCure, rPowerM)) * 
                          EXPT(1.0 - rEstimatedDegreeOfCure, rPowerN);
    rEstimatedDegreeOfCure := rEstimatedDegreeOfCure + (rInstantaneousRate * rDeltaSeconds);
    IF rEstimatedDegreeOfCure > 1.0 THEN rEstimatedDegreeOfCure := 1.0; END_IF;
END_IF;

(* Dynamic Viscosity Profile Calculation *)
IF rEstimatedDegreeOfCure < rGelationAlpha THEN
    rEstimatedViscosity_Pa_s := rBaseViscosity * EXP(rViscosityActEnergy / (rR_GasConstant * rAbsoluteTempKelvin)) * 
                                EXPT(rGelationAlpha / (rGelationAlpha - rEstimatedDegreeOfCure), 1.5 + 2.0 * rEstimatedDegreeOfCure);
ELSE
    rEstimatedViscosity_Pa_s := 10000.0; (* Solidified gel state reached *)
    bGelationReached := TRUE;
END_IF;

(* Evaluate minimum viscosity dynamic pressure window *)
IF (rEstimatedViscosity_Pa_s <= rMinViscosityPressureWindow) AND NOT bGelationReached THEN
    bResinMinimumViscosityMet := TRUE;
END_IF;

(* ========================================================================================= *)
(* MASTER MULTI-STAGE CASE FINITE STATE MACHINE (AEROSPACE CURE CYCLE)                      *)
(* ========================================================================================= *)
CASE iCurrentCurePhase OF

    0: (* PHASE 0: IDLE / SYSTEM READY INITIALIZATION *)
        sCurrentPhaseDescription := 'IDLE_STANDBY';
        bSystemReady := bSafetyInterlockOK AND (wAlarmWord = 16#0000);
        bCycleCompleted := FALSE;
        rHeaterThyristorPowerPct := 0.0;
        rExchangerCoolingDamperPct := 0.0;
        rPressurizationValvePct := 0.0;
        rExhaustBleedValvePct := 100.0; (* Vessel naturally vented *)
        rVacuumBagVentValvePct := 0.0;   (* Full vacuum source open *)

        rThermalIntegral := 0.0;
        rPressureIntegral := 0.0;

        IF bEnable AND bSystemReady THEN
            iCurrentCurePhase := 10;
        END_IF;

    10: (* PHASE 10: VACUUM BAG INTEGRITY & DECAY LEAK CHECK (AMS 2750/MIL-HDBK) *)
        sCurrentPhaseDescription := 'VACUUM_HOLD_CHECK';
        bSystemReady := TRUE;
        rExhaustBleedValvePct := 100.0;

        tVacuumHoldTimer(IN := TRUE, PT := T#120S);
        IF tVacuumHoldTimer.ET = T#0S THEN
            rVacuumIntegrityStart_mbar := rVacuumBagPressure_mbar;
        END_IF;

        IF tVacuumHoldTimer.Q THEN
            tVacuumHoldTimer(IN := FALSE);
            (* Evaluate vacuum leak drop rate *)
            rVacuumLeakRate_mbar_per_min := (rVacuumBagPressure_mbar - rVacuumIntegrityStart_mbar) / 2.0;
            IF (rVacuumBagPressure_mbar > 25.0) OR (rVacuumLeakRate_mbar_per_min > 5.0) THEN
                wAlarmWord := wAlarmWord OR C_ALARM_VACUUM_BAG_BREACH;
                iCurrentCurePhase := 900; (* Graceful abort *)
            ELSE
                iCurrentCurePhase := 20; (* Integrity verified *)
            END_IF;
        END_IF;

    20: (* PHASE 20: CONTROLLED RAMP TO DEGASSING & CONSOLIDATION DWELL (1.8 C/min) *)
        sCurrentPhaseDescription := 'RAMP_TO_DEGASSING';

        (* Gradient mitigation override *)
        IF rObservedMaxGradient_degC > (rMaxAllowableGradient * 0.85) THEN
            (* Hold heating ramp to allow thermal conduction equilibrium *)
            rThermalError := 0.0;
            wWarningWord := wWarningWord OR C_WARN_RAMP_LAG;
        ELSE
            (* Closed-loop thermal rate tracking *)
            rThermalError := rRampRateSetpoint - rFilteredHeatingRate_C_min;
        END_IF;

        rThermalIntegral := rThermalIntegral + (rThermalError * rDeltaSeconds * 0.4);
        IF rThermalIntegral > rThermalIntegralMax THEN rThermalIntegral := rThermalIntegralMax; END_IF;
        IF rThermalIntegral < rThermalIntegralMin THEN rThermalIntegral := rThermalIntegralMin; END_IF;

        rHeatOutputEffort := (rThermalError * 15.0) + rThermalIntegral;
        IF rHeatOutputEffort > 100.0 THEN rHeaterThyristorPowerPct := 100.0;
        ELSIF rHeatOutputEffort < 0.0 THEN rHeaterThyristorPowerPct := 0.0;
        ELSE rHeaterThyristorPowerPct := rHeatOutputEffort; END_IF;

        rExchangerCoolingDamperPct := 0.0;

        (* Trigger Phase 30 when reaching degassing dwell plateau (110.0 deg C) *)
        IF rVotedLeadingEdgeTemp >= 110.0 THEN
            iCurrentCurePhase := 30;
            tStateTimer(IN := FALSE);
        END_IF;

    30: (* PHASE 30: RESIN VISCOSITY TROUGH MONITORING & DYNAMIC COMPACT PRESSURE *)
        sCurrentPhaseDescription := 'DYNAMIC_PRESSURIZATION';

        (* Hold degassing plateau temperature at 115 deg C *)
        rThermalError := 115.0 - rVotedLeadingEdgeTemp;
        rHeaterThyristorPowerPct := LIMIT(0.0, (rThermalError * 4.5) + 25.0, 70.0);

        (* Dynamic Consolidation Pressurization Trigger *)
        IF bResinMinimumViscosityMet OR (rEstimatedViscosity_Pa_s <= rMinViscosityPressureWindow) THEN
            (* Modulate autoclave nitrogen pressure to 6.89 bar *)
            rPressureError := rTargetAutoclavePressure_Bar - rAutoclaveVesselPressure_Bar;
            rPressureIntegral := rPressureIntegral + (rPressureError * rDeltaSeconds * 0.5);
            rPressureEffort := (rPressureError * 35.0) + rPressureIntegral;

            IF rPressureEffort > 0.0 THEN
                rPressurizationValvePct := LIMIT(0.0, rPressureEffort, 100.0);
                rExhaustBleedValvePct := 0.0;
            ELSE
                rPressurizationValvePct := 0.0;
                rExhaustBleedValvePct := LIMIT(0.0, -1.0 * rPressureEffort, 100.0);
            END_IF;

            (* Bag backfill / vent to prevent pinholing resin bleeding under 7 bar *)
            rVacuumBagVentValvePct := 100.0;

            (* Once autoclave vessel is stabilized at >= 95% consolidation pressure *)
            IF rAutoclaveVesselPressure_Bar >= (rTargetAutoclavePressure_Bar * 0.95) THEN
                iCurrentCurePhase := 40;
            END_IF;
        END_IF;

    40: (* PHASE 40: SECONDARY RAMP TO HIGH-TEMPERATURE ISOTHERMAL CURE SOAK *)
        sCurrentPhaseDescription := 'RAMP_TO_FINAL_CURE';

        (* Maintain consolidation pressure *)
        rPressurizationValvePct := LIMIT(0.0, (rTargetAutoclavePressure_Bar - rAutoclaveVesselPressure_Bar) * 40.0, 100.0);

        (* Rate controlled ramp to final cure temperature (e.g. 177 C) *)
        IF rObservedMaxGradient_degC > rMaxAllowableGradient THEN
            (* Restrict power if laminate core lags or overshoots *)
            rHeaterThyristorPowerPct := 10.0;
        ELSE
            rThermalError := rSetpointCureTemp - rVotedLeadingEdgeTemp;
            rHeaterThyristorPowerPct := LIMIT(0.0, (rThermalError * 3.2), 95.0);
        END_IF;

        IF rVotedLeadingEdgeTemp >= (rSetpointCureTemp - 1.5) THEN
            iCurrentCurePhase := 50;
            tCureDwellTimer(IN := FALSE);
        END_IF;

    50: (* PHASE 50: HIGH-TEMPERATURE ISOTHERMAL SOAK & DEGREE OF CURE INTEGRATION *)
        sCurrentPhaseDescription := 'ISOTHERMAL_CURE_HOLD';

        (* Precision Isothermal PID Temperature Regulation *)
        rThermalError := rSetpointCureTemp - rVotedLeadingEdgeTemp;
        rThermalIntegral := rThermalIntegral + (rThermalError * rDeltaSeconds * 0.1);
        rThermalIntegral := LIMIT(0.0, rThermalIntegral, 60.0);
        rHeaterThyristorPowerPct := LIMIT(0.0, (rThermalError * 5.0) + rThermalIntegral, 80.0);

        (* Exotherm watch in thick core section *)
        IF rTC_Zone2_LaminateCore > (rSetpointCureTemp + 5.0) THEN
            rHeaterThyristorPowerPct := 0.0;
            rExchangerCoolingDamperPct := 25.0; (* Active exotherm suppression *)
        ELSE
            rExchangerCoolingDamperPct := 0.0;
        END_IF;

        (* Minimum soak time (120 minutes) AND Degree of Cure verification (Alpha >= 0.94) *)
        tCureDwellTimer(IN := TRUE, PT := T#7200S);
        IF tCureDwellTimer.Q AND (rEstimatedDegreeOfCure >= 0.94) THEN
            tCureDwellTimer(IN := FALSE);
            iCurrentCurePhase := 60; (* Initiate controlled cool-down *)
        END_IF;

    60: (* PHASE 60: CONTROLLED RESIDUAL STRESS COOL-DOWN (-1.5 C/min limit) *)
        sCurrentPhaseDescription := 'CONTROLLED_COOLDOWN';

        rHeaterThyristorPowerPct := 0.0;

        (* Regulate cooling exchanger damper to maintain safe cooling slope without thermal shock *)
        IF rFilteredHeatingRate_C_min < -2.2 THEN
            (* Cooling too fast: choke cooling damper *)
            rExchangerCoolingDamperPct := 5.0;
        ELSIF rFilteredHeatingRate_C_min > -1.0 THEN
            (* Cooling too slow: open damper *)
            rExchangerCoolingDamperPct := LIMIT(0.0, rExchangerCoolingDamperPct + 2.0, 85.0);
        END_IF;

        (* Maintain consolidation pressure until part core drops below Glass Transition Tg *)
        IF rVotedLeadingEdgeTemp <= 60.0 AND rTC_Zone2_LaminateCore <= 60.0 THEN
            iCurrentCurePhase := 70;
        END_IF;

    70: (* PHASE 70: DEPRESSURIZATION AND EXHAUST CYCLE *)
        sCurrentPhaseDescription := 'DEPRESSURIZING';

        rHeaterThyristorPowerPct := 0.0;
        rExchangerCoolingDamperPct := 0.0;
        rPressurizationValvePct := 0.0;

        (* Controlled exhaust bleed: maintain depressurization rate <= 0.5 bar/min *)
        rExhaustBleedValvePct := 40.0;

        IF rAutoclaveVesselPressure_Bar <= 0.15 THEN
            rExhaustBleedValvePct := 100.0;
            iCurrentCurePhase := 80;
        END_IF;

    80: (* PHASE 80: CURE CYCLE CERTIFIED COMPLETE *)
        sCurrentPhaseDescription := 'CYCLE_COMPLETED_CERTIFIED';
        bCycleCompleted := TRUE;
        bSystemReady := TRUE;
        rHeaterThyristorPowerPct := 0.0;
        rExchangerCoolingDamperPct := 0.0;
        rPressurizationValvePct := 0.0;
        rExhaustBleedValvePct := 100.0;
        rVacuumBagVentValvePct := 100.0;

        IF NOT bEnable THEN
            iCurrentCurePhase := 0; (* Reset back to standby *)
        END_IF;

    900: (* PHASE 900: GRACEFUL EXOTHERM SUPPRESSION & CONTROLLED ABORT *)
        sCurrentPhaseDescription := 'EXOTHERM_SUPPRESSION_ABORT';
        rHeaterThyristorPowerPct := 0.0;
        rExchangerCoolingDamperPct := 100.0; (* Full cooling stream *)
        rPressurizationValvePct := 0.0;
        rExhaustBleedValvePct := 20.0;       (* Modulate slow venting to retain consolidation *)

        tExothermGraceTimer(IN := TRUE, PT := T#600S);
        IF (rObservedMaxGradient_degC < 10.0) AND (rVotedLeadingEdgeTemp < 80.0) THEN
            tExothermGraceTimer(IN := FALSE);
            iCurrentCurePhase := 70;
        ELSIF tExothermGraceTimer.Q THEN
            tExothermGraceTimer(IN := FALSE);
            iCurrentCurePhase := 999;
        END_IF;

    999: (* PHASE 999: CRITICAL HARD EMERGENCY FAILSAFE SHUTDOWN *)
        sCurrentPhaseDescription := 'EMERGENCY_SHUTDOWN_LATCHED';
        bSystemReady := FALSE;
        rHeaterThyristorPowerPct := 0.0;
        rExchangerCoolingDamperPct := 100.0; (* Safe full cooling to quench runaways *)
        rPressurizationValvePct := 0.0;
        rExhaustBleedValvePct := 100.0;      (* Emergency vessel blowdown *)
        rVacuumBagVentValvePct := 100.0;

END_CASE;

END_FUNCTION_BLOCK
